import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner sc =  new Scanner(System.in);
		int t = sc.nextInt();
		int b = 0;
		while(b<t){
		    int n = sc.nextInt();
		    int []arr = new int[3*n];
		    
		    for(int i=0;i<3*n;i++){
		        arr[i]=sc.nextInt();
		    }
		    
		    Arrays.sort(arr);
		    
		    long []p = new long[3*n+1];
		    
		    for(int i=0;i<3*n;i++){
		        p[i+1]=p[i]+arr[3*n-1-i];
		    }
		    
		    long maxScore = 0;
		    
		    for(int v=0;v<=2*n;v++){
		        int l = Math.max(0,v-n);
		        int r = v/2;
		        
		        while(r-l>=3){
		            int m1 = l + (r - l)/3;
		            int m2 = r - (r - l)/3;
		            long val1 = 2*p[m1] + p[2*v -3 *m1];
		            long val2 = 2*p[m2] + p[2*v - 3*m2];
		            
		            if(val1<val2){
		                l=m1+1;
		                continue;
		            }
		            if(val1>val2){
		                r=m2-1;
		                continue;
		            }
		            l=m1;
		            r=m2;
		        }
		        long maxG = -1;
		        for(int a=l;a<=r;a++){
		            long curr = 2*p[a] + p[2*v -3*a];
		            if(curr>maxG){
		                maxG = Math.max(maxG,curr);
		            }
		        }
		        
		        long  currScore = maxG + 3*p[3*n-v];
		        maxScore = Math.max(maxScore,currScore);
		    }
		    System.out.println(maxScore);
		    
		    
		    
		    b++;
		}
	}
}
